@CrossOrigin
@RestController
@RequestMapping("/OperationQuery")
public class OperationQueryRestController extends BaseSpringRestController {
	
	public OperationQueryRestController( OperationService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Operation using a UUID
     * @param		UUID operationId
     * @return		Operation
     */    
    @GetMapping("/load")
    public Operation load( @RequestParam(required=true) UUID operationId ) {
    	Operation entity = null;

    	try {  
    		entity = service.getOperation( new OperationFetchOneSummary( operationId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Operation using Id " + operationId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Operation business objects
     * @return		Set<Operation>
     */
    @GetMapping("/")
    public List<Operation> loadAll() {                
    	List<Operation> operationList = null;
        
    	try {
            // load the Operation
            operationList = service.getAllOperation();
            
            if ( operationList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Operations" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Operations ", exc );
        	return null;
        }

        return operationList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Operation operation = null;
    protected OperationService service = null;
    private static final Logger LOGGER = Logger.getLogger(OperationQueryRestController.class.getName());
    
}
